@@ -0,0 +1,18 @@
+package hotel.messages;
+
+import java.util.List;
+
+/** Every message sent is followed by a copy for the archive. */
+public final class ArchiveCopyRule implements MessageRule {
+
+    private final String archiveAddress;
+
+    public ArchiveCopyRule(String archiveAddress) {
+        this.archiveAddress = archiveAddress;
+    }
+
+    @Override
+    public List<Draft> apply(Draft draft) {
+        return List.of(draft, draft.withTo(archiveAddress).withSubject("[Cópia] " + draft.subject()));
+    }
+}
diff --git a/src/main/java/hotel/messages/Draft.java b/src/main/java/hotel/messages/Draft.java
new file mode 100644
index 0000000..92adc3a
--- /dev/null
+++ b/src/main/java/hotel/messages/Draft.java
@@ -0,0 +1,29 @@
+package hotel.messages;
+
+/** An e-mail on its way out, which the rules may block, change or accompany with other e-mails. */
+public record Draft(String to, String subject, String body, MessageStatus status) {
+
+    public static Draft of(String to, String subject, String body) {
+        return new Draft(to, subject, body, MessageStatus.SENT);
+    }
+
+    public boolean blocked() {
+        return status == MessageStatus.BLOCKED;
+    }
+
+    public Draft asBlocked() {
+        return new Draft(to, subject, body, MessageStatus.BLOCKED);
+    }
+
+    public Draft withTo(String newTo) {
+        return new Draft(newTo, subject, body, status);
+    }
+
+    public Draft withSubject(String newSubject) {
+        return new Draft(to, newSubject, body, status);
+    }
+
+    public Draft withBody(String newBody) {
+        return new Draft(to, subject, newBody, status);
+    }
+}
diff --git a/src/main/java/hotel/messages/EmailSender.java b/src/main/java/hotel/messages/EmailSender.java
index 3eee255..ee106b3 100644
--- a/src/main/java/hotel/messages/EmailSender.java
+++ b/src/main/java/hotel/messages/EmailSender.java
@@ -1,15 +1,51 @@
 package hotel.messages;

-/** Sends e-mails to guests. Every e-mail sent is kept in the list of sent messages. */
+import java.util.ArrayList;
+import java.util.List;
+
+/**
+ * Sends e-mails to guests, after the rules of the installation have had their say. Every e-mail, sent or
+ * blocked, is kept in the list of sent messages.
+ */
 public final class EmailSender {

     private final SentMessages sentMessages;
+    private final List<MessageRule> rules;

+    /** A sender without rules: every e-mail goes out as it is. */
     public EmailSender(SentMessages sentMessages) {
+        this(sentMessages, List.of(), false);
+    }
+
+    public EmailSender(SentMessages sentMessages, List<ScopedRule> rules, boolean testMode) {
         this.sentMessages = sentMessages;
+        this.rules = rules.stream()
+                .filter(scoped -> scoped.scope().appliesTo(testMode))
+                .map(ScopedRule::rule)
+                .toList();
     }

-    public Message send(String to, String subject, String body) {
-        return sentMessages.add("EMAIL", to, subject, body);
+    /** Returns the message that was asked for (the first one recorded), whether it was sent or blocked. */
+    public synchronized Message send(String to, String subject, String body) {
+        List<Draft> drafts = List.of(Draft.of(to, subject, body));
+        for (MessageRule rule : rules) {
+            List<Draft> next = new ArrayList<>();
+            for (Draft draft : drafts) {
+                if (draft.blocked()) {
+                    next.add(draft);
+                } else {
+                    next.addAll(rule.apply(draft));
+                }
+            }
+            drafts = next;
+        }
+        Message first = null;
+        for (Draft draft : drafts) {
+            Message message = sentMessages.add("EMAIL", draft.to(), draft.subject(), draft.body(), draft.status());
+            if (first == null) {
+                first = message;
+            }
+        }
+        return first;
     }
 }
